test('4671完整28422与1873真实首轮研究参考及首授next-use，PP吸取补满与次轮600固吸分别结算',()=>{
 const s=make(28422,null,{whole:true,fullSoul:true,hp:1000,policies:{qualifiedFirstReference1873:9000,qualifiedFirst4671:{1927:'next-use'},qualifiedConversionDuration4671:3,qualifiedHitUnit1873:'first-hit-once'}}),raw=enemySource.moves.find(x=>x.id===20030),out=E.WIKI.effectsEngine.compileInstances(raw.effectInstances,enemySource.effects,raw);assert.equal(out.issue,'');s.moveDefinitions[key(20030)].operations=out.operations;assert.deepEqual(s.moveDefinitions[key(28422)].operations.map(x=>x.index),[0,1,2,3]);assert.equal(s.fighters[0].moves.length,5);assert.equal(s.fighters[0].moves.filter(k=>s.moveDefinitions[k].fifth).length,1);
 let ppBefore,ppHit,enemyPPHit;turn(s,28422,20030,{before(ev,c){if(ev==='beforeUse'&&c.a.side===0)ppBefore=c.a.pp[key(28422)];},after(ev,c){if(ev==='afterHit'&&c.a.side===0){ppHit=c.a.pp[key(28422)];enemyPPHit=c.t.pp[key(20030)];}}});
 assert.equal(ppBefore,4);assert.equal(ppHit,5);assert.equal(enemyPPHit,33);assert.equal(s.fighters[0].pp[key(28422)],5);assert.equal(s.fighters[1].pp[key(20030)],32);assert.equal(s.fighters[1].pp[key(10086)],33);assert.deepEqual(stats.map(k=>s.fighters[0].stages[k]),Array(6).fill(2));assert.equal(s.fighters[1].stages.spe,1);assert.equal(dmg(s,'percent'),3000);assert.equal(dmg(s,'fixed'),0);assert.equal(s.fighters[0].hp,4000);assert.equal(s.fighters[1].hp,6000);
 turn(s,10047,20030);assert.equal(s.fighters[0].soulState.clawPreviousStartHP1873,4000);assert.equal(s.fighters[0].soulState.clawFast1873,2);assert.equal(s.fighters[0].soulState.clawDrain1873,0);assert.equal(s.fighters[0].soulState.resolvedPriority.value,3);assert.equal(dmg(s,'percent'),0);assert.equal(dmg(s,'fixed'),600);assert.ok(dmg(s)>0);assert.equal(s.fighters[0].hp,4600);assert.equal(s.fighters[1].hp,6000-dmg(s)-600);assert.ok(s.fighters[1].stages.def<=-1);assert.ok(s.fighters[1].stages.spd<=-1);assert.equal(s.fighters[0].pp[key(10047)],source.moves.find(x=>x.id===10047).pp-1);assert.equal(s.fighters[1].pp[key(20030)],31);
})

