 let atUse;turn(s,21329,20030,{after(ev,c){if(ev==='afterUse'&&c.a.side===0)atUse={hp:c.a.hp,burn:c.t.ailments['烧伤'],enemy:c.t.hp,percent:c.damageTotal(c.t,'percent')};}});assert.equal(s.fighters[0].soulState.resolvedPriority.value,2);assert.equal(dmg(s,'fixed'),600);assert.equal(atUse.hp,1600);assert.ok(atUse.burn>=2);assert.equal(atUse.enemy,8400);assert.equal(atUse.percent,0);assert.equal(dmg(s,'percent'),1125);assert.equal(s.fighters[1].hp,7275);assert.equal(s.fighters[0].hp,1600);assert.equal(s.fighters[0].stages.acc,4);assert.equal(s.fighters[0].pp[key(21329)],source.moves.find(x=>x.id===21329).pp-1);
 turn(s,21329);assert.equal(s.fighters[0].soulState.resolvedPriority.value,2);assert.equal(dmg(s,'fixed'),600);assert.equal(s.fighters[0].hp,2200);turn(s,21329);assert.equal(s.fighters[0].soulState.resolvedPriority.value,0);assert.equal(dmg(s,'fixed'),600);assert.equal(s.fighters[0].hp,2800);turn(s,21329);assert.equal(s.fighters[0].soulState.resolvedPriority.value,0);assert.equal(dmg(s,'fixed'),0);assert.equal(s.fighters[0].hp,2800);assert.equal(s.fighters[0].pp[key(21329)],source.moves.find(x=>x.id===21329).pp-4);
